template.inlineTemplate:
cd ${instance-EXPORT_PATH}
echo "copying client certificate to p12 keystore file ${instance-GENERIC_CLIENT_USER}-keystore.p12" cp "//'${instance-EXPORT_HLQ}.${instance-GENERIC_CLIENT_USER}'" ${instance-GENERIC_CLIENT_USER}-keystore.p12 echo "copying server certificate to temporary file ${instance-GENERIC_CLIENT_USER}-server.crt" cp "//'${instance-EXPORT_HLQ}.${instance-GENERIC_CLIENT_USER}.SERVERCA'" ${instance-GENERIC_CLIENT_USER}-server.crt
echo "creating client *.key and *.crt files" openssl pkcs12 -in ${instance-GENERIC_CLIENT_USER}-keystore.p12 -out ${instance-GENERIC_CLIENT_USER}.crt -clcerts -nokeys -passin pass:${instance-EXPORT_PASSWORD} openssl pkcs12 -in ${instance-GENERIC_CLIENT_USER}-keystore.p12 -out ${instance-GENERIC_CLIENT_USER}.key -nocerts -nodes -passin pass:${instance-EXPORT_PASSWORD}
echo "importing the ${instance-GENERIC_CLIENT_USER}-server.crt file into the p12 truststore file ${instance-GENERIC_CLIENT_USER}-truststore.p12" keytool -importcert -file ${instance-GENERIC_CLIENT_USER}-server.crt -noprompt -keystore ${instance-GENERIC_CLIENT_USER}-truststore.p12 -alias serverca -storepass ${instance-EXPORT_PASSWORD} if [ $? -gt 0 ]; then echo "Error importing certificate to keystore, keeping temporary server certificate file" else echo "Server certificate successfully imported" fi
echo "All files have been exported to ${instance-EXPORT_PATH}"
